func (this *Test_org_eclipse_swt_custom_StyledText) Test_getSelectionRange() {
	var testText string = "Line1\r\nLine2"
	var invalidRanges [][]int32 = [][]int32{[]int32{-1, 0}, []int32{-1, -1}, []int32{100, 1}, []int32{100, -1}, []int32{12, 1}, []int32{11, 2}, []int32{2, -3}, []int32{50, -1}}
	var selectionRanges [][]int32 = [][]int32{[]int32{0, 1}, []int32{0, 0}, []int32{2, 3}, []int32{12, 0}, []int32{2, -2}, []int32{5, -1}}
	for _, invalidRange := range invalidRanges {
		var start int32 = invalidRange[0]
		var length int32 = invalidRange[1]
		func() {
			defer func() {
				r := recover()
				if r == nil {
					return
				}
				if func() bool {
					switch r.(type) {
					case *jrt.IllegalArgumentException:
						return true
					}
					return false
				}() {
					e := r.(*jrt.IllegalArgumentException)
					_ = e
					junit.Fail("should not throw exception for out of range")
				} else {
					panic(r)
				}
			}()
			this.text.SetSelectionRange(start, length)
		}()
	}
	this.text.SetSelectionRange(0, 0)
	junit.AssertTrue(this.text.GetSelectionRange().X == 0 && this.text.GetSelectionRange().Y == 0)
	this.text.SetText(testText)
	for i := int32(0); i < int32(len(selectionRanges)); i++ {
		var start int32 = selectionRanges[i][0]
		var length int32 = selectionRanges[i][1]
		this.text.SetSelectionRange(start, length)
		if length < 0 {
			start += length
			length *= -1
			junit.AssertEquals(int32(start), int32(this.text.GetCaretOffset()))
		} else {
			junit.AssertEquals(int32(start+length), int32(this.text.GetCaretOffset()))
		}
		junit.AssertTrue(this.text.GetSelectionRange().X == start && this.text.GetSelectionRange().Y == length)
	}
	for _, invalidRange := range invalidRanges {
		var start int32 = invalidRange[0]
		var length int32 = invalidRange[1]
		func() {
			defer func() {
				r := recover()
				if r == nil {
					return
				}
				if func() bool {
					switch r.(type) {
					case *jrt.IllegalArgumentException:
						return true
					}
					return false
				}() {
					e := r.(*jrt.IllegalArgumentException)
					_ = e
					junit.Fail("should not throw exception for out of range")
				} else {
					panic(r)
				}
			}()
			this.text.SetSelectionRange(start, length)
		}()
	}
}

