func (this *Test_org_eclipse_swt_custom_StyledText) Test_setStyleRanges_render() {
	junit.AssumeFalse(SwtTestUtilIsCocoa, "Bug 553090 prevents test to work on Mac")
	this.shell.SetVisible(true)
	this.text.SetText("abc")
	this.text.SetMargins(0, 0, 0, 0)
	this.text.Pack()
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, func() bool {
		return SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()) && !SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED))
	})
	junit.AssertTrue(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()))
	junit.AssertFalse(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED)))
	this.text.SetStyleRangesRanges([]*swt.StyleRange{swt.NewStyleRangeStartLengthForegroundBackground(0, 1, nil, this.text.GetDisplay().GetSystemColor(swt.COLOR_RED)), swt.NewStyleRangeStartLengthForegroundBackground(2, 1, nil, this.text.GetDisplay().GetSystemColor(swt.COLOR_RED))})
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(100, func() bool {
		return SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()) && SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED))
	})
	junit.AssertTrue(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()))
	junit.AssertTrue(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED)))
	this.text.ReplaceStyleRanges(0, 3, []*swt.StyleRange{swt.NewStyleRangeStartLengthForegroundBackground(0, 3, nil, this.text.GetDisplay().GetSystemColor(swt.COLOR_RED))})
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, func() bool {
		return !SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()) && SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED))
	})
	junit.AssertFalse(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetBackground()))
	junit.AssertTrue(SwtTestUtilHasPixel(upcastswtStyledTextToswtControl(this.text), this.text.GetDisplay().GetSystemColor(swt.COLOR_RED)))
}

