func (this *Test_org_eclipse_swt_custom_StyledText) RtfCopy() {
	var lines string = "Line0\nLine1\nLine2\nLine3\nLine4\nLine5"
	var linesCalled []int32 = []int32{0}
	var listener swt.LineStyleListener = &LineStyleListenerFunc{fn: func(event *swt.LineStyleEvent) {
		var display *swt.Display = swt.DisplayGetDefault()
		var red *swt.Color = display.GetSystemColor(swt.COLOR_RED)
		var styledText *swt.StyledText = castswtWidgetToswtStyledText(event.Widget)
		var lineIndex int32 = styledText.GetLineAtOffset(event.LineOffset)
		var lineStart int32 = event.LineOffset
		var lineEnd int32 = lineStart + jrt.StringLength(event.LineText)
		var goodRange *swt.StyleRange = swt.NewStyleRangeStartLengthForegroundBackground(0, 1, red, red)
		event.Styles = make([]*swt.StyleRange, 2)
		switch lineIndex % 6 {
		case 0:
			event.Styles[0] = goodRange
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineEnd, 1, red, red)
			linesCalled[0]++
			break
		case 1:
			event.Styles[0] = goodRange
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineEnd, -1, red, red)
			linesCalled[0]++
			break
		case 2:
			event.Styles[0] = goodRange
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineEnd-1, -1, red, red)
			linesCalled[0]++
			break
		case 3:
			event.Styles[0] = goodRange
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineStart, -1, red, red)
			linesCalled[0]++
			break
		case 4:
			event.Styles[0] = swt.NewStyleRangeStartLengthForegroundBackground(lineStart, 1, red, red)
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineStart, -1, red, red)
			linesCalled[0]++
			break
		case 5:
			event.Styles[0] = swt.NewStyleRangeStartLengthForegroundBackground(lineEnd/2, 1, red, red)
			event.Styles[1] = swt.NewStyleRangeStartLengthForegroundBackground(lineEnd/2, -1, red, red)
			linesCalled[0]++
			break
		}
	}}
	this.text.SetText(lines)
	this.text.SetSelectionStartEnd(0, this.text.GetCharCount())
	this.text.AddLineStyleListener(listener)
	linesCalled[0] = 0
	this.text.Copy()
	junit.AssertEquals(int32(2*this.text.GetLineCount()), int32(linesCalled[0]))
	var clipboard *swt.Clipboard = swt.NewClipboard(this.text.GetDisplay())
	var rtfTranfer *swt.RTFTransfer = swt.RTFTransferGetInstance()
	var clipboardText string = jrt.Cast[string](clipboard.GetContents(upcastswtRTFTransferToswtTransfer(rtfTranfer)))
	junit.AssertTrue(jrt.StringLength(clipboardText) > 0)
	var htmlTranfer *swt.HTMLTransfer = swt.HTMLTransferGetInstance()
	clipboardText = jrt.Cast[string](clipboard.GetContents(upcastswtHTMLTransferToswtTransfer(htmlTranfer)))
	junit.AssertTrue(jrt.StringLength(clipboardText) > 0)
	clipboard.Dispose()
	this.text.RemoveLineStyleListener(listener)
}

