func (this *Test_org_eclipse_swt_custom_StyledText) Test_bug551335_lostStyles() {
	junit.AssumeFalse(SwtTestUtilIsCocoa, "Bug 536588 prevents test to work on Mac")
	this.shell.SetVisible(true)
	this.text.SetText("012345678\n012345678\n0123456789")
	this.text.SetMargins(0, 0, 0, 0)
	this.text.Pack()
	this.shell.Pack()
	var style *swt.StyleRange = swt.NewStyleRange()
	style.Background = Test_org_eclipse_swt_custom_StyledTextBLUE
	style.Length = 3
	var styles []*swt.StyleRange = make([]*swt.StyleRange, 3)
	style.Start = 3
	styles[0] = castanyToswtStyleRange(style.Clone())
	style.Start = 13
	styles[1] = castanyToswtStyleRange(style.Clone())
	style.Start = 23
	styles[2] = castanyToswtStyleRange(style.Clone())
	var lineHeight int32 = this.text.GetBounds().Height / this.text.GetLineCount()
	var testAreas []*swt.Rectangle = make([]*swt.Rectangle, this.text.GetLineCount())
	for i := int32(0); i < int32(len(testAreas)); i++ {
		testAreas[i] = swt.NewRectangle(0, int32(((float64(i) + 0.48) * float64(lineHeight))), 1000, 3)
	}
	var testAllLinesStyled func() bool = func() bool {
		for _, testArea := range testAreas {
			if !SwtTestUtilHasPixelControlExpectedColorRect(upcastswtStyledTextToswtControl(this.text), Test_org_eclipse_swt_custom_StyledTextBLUE, testArea) {
				return false
			}
		}
		return true
	}
	var testUnstyledText func() bool = func() bool {
		for _, testArea := range testAreas {
			if SwtTestUtilHasPixelControlExpectedColorRect(upcastswtStyledTextToswtControl(this.text), Test_org_eclipse_swt_custom_StyledTextBLUE, testArea) {
				return false
			}
		}
		return true
	}
	for _, s := range styles {
		this.text.SetStyleRange(s)
	}
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testAllLinesStyled)
	junit.AssertTrue(testAllLinesStyled())
	this.text.SetStyleRange(nil)
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testUnstyledText)
	junit.AssertTrue(testUnstyledText())
	this.text.SetStyleRangesRanges(styles)
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testAllLinesStyled)
	junit.AssertTrue(testAllLinesStyled())
	this.text.SetStyleRange(nil)
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testUnstyledText)
	junit.AssertTrue(testUnstyledText())
	var ranges []int32 = make([]int32, int32(len(styles))*2)
	style.Length = 0
	style.Start = style.Length
	for i := int32(0); i < int32(len(styles)); i++ {
		ranges[i*2] = styles[i].Start
		ranges[i*2+1] = styles[i].Length
		styles[i] = style
	}
	this.text.SetStyleRangesRangesStyles(ranges, styles)
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testAllLinesStyled)
	junit.AssertTrue(testAllLinesStyled())
	this.text.SetStyleRange(nil)
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(1000, testUnstyledText)
	junit.AssertTrue(testUnstyledText())
}

func (this *Test_org_eclipse_swt_custom_StyledText) Test_clipboardCarryover() {
	junit.AssumeFalse(SwtTestUtilIsCocoa, "Disabled on Mac because similar clipboard tests are also disabled.")
	abs125 := jrt.NewRandom().NextInt()
	if abs125 < 0 {
		abs125 = -abs125
	}
	var content string = fmt.Sprintf("StyledText-%d", abs125)
	this.text.SetText(content)
	this.text.SelectAll()
	this.text.Copy()
	this.text.Dispose()
	this.text = swt.NewStyledText(upcastswtShellToswtComposite(this.shell), swt.NONE)
	this.impl.setWidget_(upcastswtStyledTextToswtWidget(this.text))
	this.text.Paste()
	junit.AssertEquals(content, this.text.GetText())
	junit.AssertEquals(int32(0), int32(int32(len(this.text.GetStyleRanges()))))
	var clipboard *swt.Clipboard = swt.NewClipboard(this.text.GetDisplay())
	var rtfTranfer *swt.RTFTransfer = swt.RTFTransferGetInstance()
	var clipboardText string = jrt.Cast[string](clipboard.GetContents(upcastswtRTFTransferToswtTransfer(rtfTranfer)))
	junit.AssertTrue(jrt.StringLength(clipboardText) > 0)
}

