func (this *Test_org_eclipse_swt_custom_StyledText) Test_backspaceAndDelete() {
	this.shell.Open()
	this.text.SetSize(10, 50)
	SwtTestUtilProcessEvents()
	var display *swt.Display = swt.DisplayGetDefault()
	var a *swt.Event = this.KeyEvent(int32('a'), swt.KeyDown, upcastswtControlToswtWidget(display.GetFocusControl()))
	var aUp *swt.Event = this.KeyEvent(int32('a'), swt.KeyUp, upcastswtControlToswtWidget(display.GetFocusControl()))
	var backspace *swt.Event = this.KeyEvent(int32(swt.BS), swt.KeyDown, upcastswtControlToswtWidget(display.GetFocusControl()))
	var backspaceUp *swt.Event = this.KeyEvent(int32(swt.BS), swt.KeyUp, upcastswtControlToswtWidget(display.GetFocusControl()))
	junit.AssertTrue(display.Post(a))
	junit.AssertTrue(display.Post(aUp))
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(10000, func() bool {
		return jrt.StringLength(this.text.GetText()) == 1
	})
	junit.AssertEquals(int32(1), int32(jrt.StringLength(this.text.GetText())))
	junit.AssertTrue(display.Post(backspace))
	junit.AssertTrue(display.Post(backspaceUp))
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(10000, func() bool {
		return jrt.StringLength(this.text.GetText()) == 0
	})
	junit.AssertEquals(int32(0), int32(jrt.StringLength(this.text.GetText())))
}

